def authorised(update: Update) -> bool:
    """Full access: video + image modes (env ALLOWED_USERS + dynamically granted)."""
    user = update.effective_user
    return bool(user) and user.id in (ALLOWED_USERS | _get_full_users())


def _get_image_users() -> set[int]:
    """Merge env var IMAGE_USERS with dynamically granted ones from state."""
    state = _load_state()
    granted = set(state.get("image_users", []))
    return _ENV_IMAGE_USERS | granted


def _grant_image_user(uid: int) -> None:
    state = _load_state()
    users = set(state.get("image_users", []))
    users.add(uid)
    state["image_users"] = list(users)
    _save_state(state)


def _revoke_image_user(uid: int) -> None:
    state = _load_state()
    users = set(state.get("image_users", []))
    users.discard(uid)
    state["image_users"] = list(users)
    _save_state(state)


def _grant_full_user(uid: int, name: str = "") -> None:
    """Grant full access (video + image + quick) dynamically."""
    state = _load_state()
    full = set(state.get("full_users", []))
    full.add(uid)
    state["full_users"] = list(full)
    img = set(state.get("image_users", []))
    img.add(uid)
    state["image_users"] = list(img)
    # Store name if provided
    names = state.get("user_names", {})
    if name:
        names[str(uid)] = name
    state["user_names"] = names
    _save_state(state)


def _get_user_name(uid: int) -> str:
    """Return stored name for a user, or their ID as string."""
    state = _load_state()
    return state.get("user_names", {}).get(str(uid), str(uid))


def _usage_keyboard() -> ReplyKeyboardMarkup:
    """Build a keyboard with one button per tracked user + Back."""
    uids = _all_tracked_uids()
    names = [_get_user_name(u) for u in uids]
    # Chunk into rows of 3
    rows = [names[i:i+3] for i in range(0, len(names), 3)]
    rows.append([BTN_BACK])
    return ReplyKeyboardMarkup(rows, resize_keyboard=True, one_time_keyboard=False)


def _usage_uid_by_name(name: str) -> int | None:
    """Reverse-lookup a uid by display name or raw id string."""
    state = _load_state()
    names = state.get("user_names", {})
    # Try exact name match
    for uid_str, n in names.items():
        if n == name:
            return int(uid_str)
    # Try raw id
    try:
        return int(name)
    except ValueError:
        return None


def _usage_summary(uids: list[int], since: datetime.datetime | None, label: str) -> str:
    """Build a usage summary string for a list of uids."""
    lines = [f"📊 Credit usage — {label}"]
    grand = 0.0
    any_data = False
    for uid in uids:
        entries = _get_usage(uid, since)
        entries = [e for e in entries if e.get("mode") != "throne"]
        if not entries:
            continue
        any_data = True
        total = sum(e["credits"] for e in entries)
        grand += total
        by_mode: dict[str, float] = {}
        for e in entries:
            by_mode[e["mode"]] = by_mode.get(e["mode"], 0) + e["credits"]
        breakdown = " | ".join(f"{m}: {v:.1f}" for m, v in sorted(by_mode.items()))
        name = _get_user_name(uid)
        lines.append(f"  {name}: {total:.1f} cr  ({breakdown})")
    if not any_data:
        lines.append("  No data for this period.")
    if len(uids) > 1 and any_data:
        lines.append(f"  ─────────────")
        lines.append(f"  Total: {grand:.1f} cr")
    lines.append("ℹ️ Estimates — excludes Throne")
    return "\n".join(lines)


def _since_for_period(period_btn: str) -> tuple[datetime.datetime | None, str]:
    now = datetime.datetime.utcnow()
    if period_btn == BTN_USAGE_DAY:
        return now.replace(hour=0, minute=0, second=0, microsecond=0), "today"
    if period_btn == BTN_USAGE_WEEK:
        return now - datetime.timedelta(days=7), "last 7 days"
    if period_btn == BTN_USAGE_MONTH:
        return now - datetime.timedelta(days=30), "last 30 days"
    return None, "all time"


def _revoke_full_user(uid: int) -> None:
    state = _load_state()
    for key in ("full_users", "image_users"):
        users = set(state.get(key, []))
        users.discard(uid)
        state[key] = list(users)
    _save_state(state)


def _get_full_users() -> set[int]:
    return set(_load_state().get("full_users", []))


# ---------------------------------------------------------------------------
# Per-user credit usage tracking (estimated cost, not balance diff)
# ---------------------------------------------------------------------------
def _estimate_video_cost(duration: int, quality: str, count: int = 1) -> float:
    """Estimate video generation cost in credits."""
    cps = QUALITY_CREDITS_PER_SEC.get(quality, 4.2)
    return round(duration * cps * count, 3)


def _estimate_image_edit_cost(quality: str) -> float:
    """Estimate image edit cost in credits (doubao model, not gpt-image-2)."""
    return IMAGE_EDIT_CREDITS.get(quality, 4.743)


def _log_usage(uid: int, credits_used: float, mode: str) -> None:
    """Append an estimated usage record for a user."""
    if credits_used <= 0:
        return
    state = _load_state()
    log_key = f"usage_log_{uid}"
    entries = state.get(log_key, [])
    entries.append({
        "ts": datetime.datetime.utcnow().isoformat(timespec="seconds"),
        "credits": round(credits_used, 4),
        "mode": mode,
    })
    state[log_key] = entries[-500:]
    _save_state(state)


def _get_usage(uid: int, since: datetime.datetime | None = None) -> list[dict]:
    """Return usage records for a user, optionally filtered by date."""
    state = _load_state()
    entries = state.get(f"usage_log_{uid}", [])
    if since is None:
        return entries
    return [e for e in entries if e["ts"] >= since.isoformat(timespec="seconds")]


def _all_tracked_uids() -> list[int]:
    """Return all user IDs that have usage records."""
    state = _load_state()
    uids = []
    for key in state:
        if key.startswith("usage_log_"):
            try:
                uids.append(int(key[len("usage_log_"):]))
            except ValueError:
                pass
    return sorted(uids)


def image_authorised(update: Update) -> bool:
    """Image edit access: ALLOWED_USERS (full) + IMAGE_USERS (image only)."""
    user = update.effective_user
    return bool(user) and user.id in (ALLOWED_USERS | _get_image_users())


def get_user_keyboard(update: Update):
    """Return the right main keyboard for this user's access level."""
    if authorised(update):
        return MAIN_KEYBOARD
    return IMAGE_ONLY_KEYBOARD


# ---------------------------------------------------------------------------
# Persistent state (default image URL + custom prompt template)
# ---------------------------------------------------------------------------
def _load_state() -> dict:
    # Try env var first (Railway persistent env var), then file.
    raw = os.environ.get(STATE_JSON_ENV, "").strip()
    if raw:
        try:
            return json.loads(raw) or {}
        except Exception:  # noqa: BLE001
            pass
    try:
        with open(STATE_FILE, "r") as f:
            return json.load(f) or {}
    except Exception:  # noqa: BLE001
        return {}


def _save_state(state: dict) -> None:
    """Persist state to file AND print the Railway env var update instruction."""
    serialised = json.dumps(state)
    # Always write to file for local dev / same-container persistence
    try:
        with open(STATE_FILE, "w") as f:
            f.write(serialised)
    except Exception:  # noqa: BLE001
        log.warning("could not persist state to %s", STATE_FILE)
    # Print the env var value so Railway auto-deploy can pick it up
    # (set STATE_JSON in Railway variables to this value for cross-deploy persistence)
    log.info("STATE_SNAPSHOT: %s", serialised)


def _user_key(uid: int, key: str) -> str:
    return f"user_{uid}_{key}"


def load_default_image(uid: int | None = None) -> str | None:
    state = _load_state()
    if uid is not None:
        per = state.get(_user_key(uid, "image_url"))
        if per:
            return per
    return state.get("default_image_url")


def save_default_image(url: str, uid: int | None = None) -> None:
    state = _load_state()
    if uid is not None:
        state[_user_key(uid, "image_url")] = url
    else:
        state["default_image_url"] = url
    _save_state(state)


def load_template(uid: int | None = None) -> str:
    """Per-user template if set, else global custom, else built-in."""
    state = _load_state()
    if uid is not None:
        per = state.get(_user_key(uid, "prompt_template"))
        if per:
            return per
    return state.get("prompt_template") or PROMPT_TEMPLATE


def save_template(text: str, uid: int | None = None) -> None:
    state = _load_state()
    key = _user_key(uid, "prompt_template") if uid is not None else "prompt_template"
    state[key] = text
    _save_state(state)


def reset_template(uid: int | None = None) -> None:
    state = _load_state()
    key = _user_key(uid, "prompt_template") if uid is not None else "prompt_template"
    state.pop(key, None)
    _save_state(state)


