# ---------------------------------------------------------------------------
# EvoLink calls  (unchanged, proven)
# ---------------------------------------------------------------------------
async def upload_image(session: aiohttp.ClientSession, img_bytes: bytes,
                       filename: str = "frame.jpg") -> str:
    form = aiohttp.FormData()
    form.add_field("file", img_bytes, filename=filename, content_type="image/jpeg")
    headers = {"Authorization": f"Bearer {EVOLINK_KEY}"}
    async with session.post(UPLOAD_URL, data=form, headers=headers) as r:
        body = await r.json()
        if r.status >= 400 or not body.get("success", True):
            raise RuntimeError(f"Image upload failed ({r.status}): {body}")
        url = (body.get("data") or {}).get("file_url")
        if not url:
            raise RuntimeError(f"No file_url in upload response: {body}")
        return url


async def submit_job(session: aiohttp.ClientSession, prompt: str,
                     image_url: str, *, duration: int, quality: str,
                     aspect_ratio: str) -> str:
    payload = {
        "model": MODEL,
        "prompt": prompt,
        "image_urls": [image_url],
        "duration": duration,
        "quality": quality,
        "aspect_ratio": aspect_ratio,
        "generate_audio": GENERATE_AUDIO,
        "content_filter": CONTENT_FILTER,
    }
    headers = {"Authorization": f"Bearer {EVOLINK_KEY}"}
    async with session.post(GEN_URL, json=payload, headers=headers) as r:
        body = await r.json()
        if r.status == 401:
            raise RuntimeError("EvoLink rejected the key (401). Check it in the dashboard.")
        if r.status == 402:
            raise RuntimeError("EvoLink balance too low (402). Top up credits.")
        if r.status >= 400:
            raise RuntimeError(f"Submit error {r.status}: {body}")
        task_id = body.get("id")
        if not task_id:
            raise RuntimeError(f"No task id returned: {body}")
        return task_id


async def poll_job(session: aiohttp.ClientSession, task_id: str) -> str:
    headers = {"Authorization": f"Bearer {EVOLINK_KEY}"}
    url = TASK_URL.format(task_id=task_id)
    req_timeout = aiohttp.ClientTimeout(total=30)
    waited = 0
    first = True
    while waited < POLL_TIMEOUT:
        try:
            async with session.get(url, headers=headers, timeout=req_timeout) as r:
                body_text = await r.text()
                if r.status != 200:
                    log.warning("poll %s HTTP %d: %s", task_id, r.status, body_text[:300])
                    await asyncio.sleep(POLL_INTERVAL)
                    waited += POLL_INTERVAL
                    continue
                try:
                    body = json.loads(body_text)
                except Exception:
                    log.error("poll %s bad JSON: %s", task_id, body_text[:300])
                    await asyncio.sleep(POLL_INTERVAL)
                    waited += POLL_INTERVAL
                    continue
                status = body.get("status")
                progress = body.get("progress", "?")
                if first:
                    log.info("poll %s FIRST: %s", task_id, body_text[:500])
                    first = False
                else:
                    log.info("poll %s → %s (%s%%)", task_id, status, progress)
                if status == "completed":
                    results = body.get("results") or []
                    if results:
                        return results[0]
                    raise RuntimeError(f"Completed but no results: {body}")
                if status == "failed":
                    err = (body.get("error") or {}).get("message", "unknown error")
                    raise RuntimeError(f"Generation failed: {err}")
                if status not in ("pending", "processing"):
                    log.warning("poll %s unexpected status '%s': %s",
                                task_id, status, body_text[:500])
        except (aiohttp.ClientError, asyncio.TimeoutError) as e:
            log.warning("poll %s network: %s", task_id, e)
        await asyncio.sleep(POLL_INTERVAL)
        waited += POLL_INTERVAL
    raise TimeoutError(f"Timed out after {POLL_TIMEOUT}s. Task id: {task_id}")


async def fetch_bytes(session: aiohttp.ClientSession, url: str):
    async with session.get(url) as r:
        r.raise_for_status()
        size = int(r.headers.get("Content-Length", 0))
        if size and size > TG_UPLOAD_LIMIT:
            return None, size
        data = await r.read()
        if len(data) > TG_UPLOAD_LIMIT:
            return None, len(data)
        return data, len(data)


async def get_credits(session: aiohttp.ClientSession):
    headers = {"Authorization": f"Bearer {EVOLINK_KEY}"}
    try:
        async with session.get(CREDITS_URL, headers=headers) as r:
            body = await r.json()
            user = (body.get("data") or {}).get("user") or {}
            val = user.get("remaining_credits")
            return float(val) if val is not None else None
    except Exception:  # noqa: BLE001
        return None


# ---------------------------------------------------------------------------
# Throne image generation
# ---------------------------------------------------------------------------
def _load_throne_image(which: int) -> bytes:
    """Return Throne template image bytes.
    1 = Failed list, 2 = Failed detail,
    3 = Cancelled list, 4 = Cancelled detail.
    """
    mapping = {
        1: THRONE_IMAGE_1_B64,
        2: THRONE_IMAGE_2_B64,
        3: THRONE_IMAGE_3_B64,
        4: THRONE_IMAGE_4_B64,
    }
    return _b64.b64decode(mapping[which])


def _parse_throne_input(text: str) -> tuple[str, int] | None:
    """Parse 'HH:MM SUM' or 'HH:MM:SS SUM' — returns (time_str, amount) or None."""
    parts = text.strip().split()
    if len(parts) < 2:
        return None
    # Last token is the amount
    try:
        amount = int(parts[-1])
    except ValueError:
        return None
    time_str = " ".join(parts[:-1])
    if amount <= 0:
        return None
    return time_str, amount


async def submit_gpt_image_job(session: aiohttp.ClientSession, prompt: str,
                               image_urls: list[str]) -> str:
    """Submit a gpt-image-2 image editing job and return the task ID."""
    payload = {
        "model": THRONE_MODEL,
        "prompt": prompt,
        "size": THRONE_SIZE,
        "quality": THRONE_QUALITY,
        "n": 1,
    }
    if image_urls:
        payload["image_urls"] = image_urls
    headers = {"Authorization": f"Bearer {EVOLINK_KEY}"}
    async with session.post(IMAGE_GEN_URL, json=payload, headers=headers) as r:
        body = await r.json()
        log.info("submit_gpt_image_job %d: %s", r.status, json.dumps(body)[:500])
        if r.status == 401:
            raise RuntimeError("EvoLink rejected the key (401).")
        if r.status == 402:
            raise RuntimeError("EvoLink balance too low (402). Top up credits.")
        if r.status >= 400:
            raise RuntimeError(f"Throne image submit error {r.status}: {body}")
        task_id = body.get("id")
        if not task_id:
            raise RuntimeError(f"No task id returned: {body}")
        return task_id


async def run_throne_edit(bot, chat_id: int, time_str: str, amount: int, variant: str = "failed", uid: int | None = None) -> None:
    """Edit both Throne template images with the given time and amount.

    Image 1 (gift list): The top row shows a "Failed" gift. Change the number
      on the left and the dollar amount on the right to match `amount`.
    Image 2 (order detail): Change the gift amount number and dollar price.

    Both edits are submitted simultaneously to save time.
    """
    if variant == "cancelled":
        img1_bytes = _load_throne_image(3)
        img2_bytes = _load_throne_image(4)
    else:
        img1_bytes = _load_throne_image(1)
        img2_bytes = _load_throne_image(2)

    status = await bot.send_message(chat_id, "👑 Uploading Throne images…")
    timeout = aiohttp.ClientTimeout(total=None)

    try:
        async with aiohttp.ClientSession(timeout=timeout) as session:
            credits_before = await get_credits(session)

            # Upload both template images
            await status.edit_text("👑 Uploading images…")
            url1 = await upload_image(session, img1_bytes, filename="throne_list.png")
            url2 = await upload_image(session, img2_bytes, filename="throne_detail.png")

            # Prompts for each image
            badge_word = "Cancelled" if variant == "cancelled" else "Failed"
            badge_color = "grey/light" if variant == "cancelled" else "red"
            prompt1 = (
                f"Edit this mobile screenshot. Make exactly two changes and nothing else:\n"
                f"1. In the phone status bar at the very top left of the screen, change the time "
                f"(e.g. 00:00) to {time_str}.\n"
                f"2. In the gift list, find the top row with the {badge_color} '{badge_word}' badge. "
                f"Change the number on the left of that row to {amount}, "
                f"and change the dollar amount on the right of that row to ${amount}.00.\n"
                f"Do NOT change anything else. Keep all other rows, text, colors, "
                f"layout, and fonts completely identical."
            )

            prompt2 = (
                f"Edit this mobile screenshot. Make exactly two changes and nothing else:\n"
                f"1. In the phone status bar at the very top left of the screen, change the time "
                f"(e.g. 00:00) to {time_str}.\n"
                f"2. Change the large bold gift amount number displayed below the gift image "
                f"to {amount}, and change the price below it (e.g. $40) to ${amount}.\n"
                f"Do NOT change anything else. Keep all other text, colors, "
                f"layout, and fonts completely identical."
            )

            # Submit both jobs concurrently
            await status.edit_text("👑 Submitting edits…")
            task1, task2 = await asyncio.gather(
                submit_gpt_image_job(session, prompt1, [url1]),
                submit_gpt_image_job(session, prompt2, [url2]),
            )

            await status.edit_text("👑 Processing… ⏳")

            # Poll both concurrently
            result_url1, result_url2 = await asyncio.gather(
                poll_job(session, task1),
                poll_job(session, task2),
            )

            # Fetch both result images
            data1, size1 = await fetch_bytes(session, result_url1)
            data2, size2 = await fetch_bytes(session, result_url2)

            import io
            # Send results as files (not compressed images)
            caption = f"👑 Throne ({variant.capitalize()}) — {time_str} · ${amount}"
            if data1:
                await bot.send_document(chat_id,
                    document=io.BytesIO(data1),
                    filename=f"throne_list_{amount}.png",
                    caption=caption)
            else:
                await bot.send_message(chat_id,
                    f"Image 1 too large ({size1/1_048_576:.1f} MB). Link:\n{result_url1}")

            if data2:
                await bot.send_document(chat_id,
                    document=io.BytesIO(data2),
                    filename=f"throne_detail_{amount}.png")
            else:
                await bot.send_message(chat_id,
                    f"Image 2 too large ({size2/1_048_576:.1f} MB). Link:\n{result_url2}")

            credits_after = await get_credits(session)
            if credits_after is not None and credits_before is not None:
                used = max(credits_before - credits_after, 0)
                if uid is not None:
                    _log_usage(uid, used, "throne")
                await bot.send_message(chat_id,
                    f"💳 {used:.2f} · {credits_after:.2f} left")
            elif credits_after is not None:
                await bot.send_message(chat_id, f"💳 {credits_after:.2f} left")

    except Exception as e:  # noqa: BLE001
        log.exception("Throne edit failed")
        await bot.send_message(chat_id, f"👑 Throne failed: {e}")
    finally:
        try:
            await status.delete()
        except Exception:  # noqa: BLE001
            pass


# ---------------------------------------------------------------------------
# Message cleanup helpers
# ---------------------------------------------------------------------------
def track(context: ContextTypes.DEFAULT_TYPE, *message_ids: int) -> None:
    """Remember bot/user message ids that should be wiped at cleanup."""
    bucket = context.user_data.setdefault("trash", [])
    bucket.extend(m for m in message_ids if m)


async def cleanup(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Delete all tracked step messages. Videos/captions are never tracked."""
    chat_id = update.effective_chat.id
    for mid in context.user_data.get("trash", []):
        try:
            await context.bot.delete_message(chat_id, mid)
        except Exception:  # noqa: BLE001 - message too old / already gone
            pass
    context.user_data["trash"] = []


async def say(update, context, text, keyboard=None):
    """Send a tracked step message (so it can be cleaned up later)."""
    msg = await update.message.reply_text(text, reply_markup=keyboard)
    track(context, msg.message_id)
    return msg


async def clear_close(update, context):
    """Delete the lingering closing message (if any) as a new flow starts."""
    prev = context.chat_data.get("last_close_id")
    if prev:
        try:
            await context.bot.delete_message(update.effective_chat.id, prev)
        except Exception:  # noqa: BLE001
            pass
        context.chat_data["last_close_id"] = None


async def close_msg(update, context, text, keyboard=None):
    """Send a 'closing' message (Done / Cancelled / Saved / Back to menu) and
    delete the PREVIOUS closing message, so at most one ever lingers. Stored in
    chat_data because it must survive user_data.clear() between conversations."""
    prev = context.chat_data.get("last_close_id")
    if prev:
        try:
            await context.bot.delete_message(update.effective_chat.id, prev)
        except Exception:  # noqa: BLE001
            pass
    kb = keyboard or get_user_keyboard(update)
    msg = await update.message.reply_text(text, reply_markup=kb)
    context.chat_data["last_close_id"] = msg.message_id
    return msg


# ---------------------------------------------------------------------------
# Generation core (shared by all modes) — runs as background task
# ---------------------------------------------------------------------------
async def run_generation(bot, chat_id, *, prompt, caption, image_url=None,
                         image_bytes=None, duration, quality, aspect_ratio, count):
    """Upload (if needed), generate COUNT clip(s), send each with the caption.

    Runs as an asyncio background task — does not block the conversation.
    Settings are snapshotted at confirm time so mid-generation changes don't leak.
    """
    status = await bot.send_message(chat_id,
        "Uploading…" if count == 1 else f"Uploading… (making {count} clips)"
    )
    timeout = aiohttp.ClientTimeout(total=None)  # no session-level cap; poll_job has its own
    try:
        async with aiohttp.ClientSession(timeout=timeout) as session:
            credits_before = await get_credits(session)
            if image_url is None:
                image_url = await upload_image(session, image_bytes)

            any_sent = False
            for i in range(count):
                tag = "" if count == 1 else f" {i+1}/{count}"
                await status.edit_text(f"Generating{tag}… 1–3 min.")
                try:
                    task_id = await submit_job(session, prompt, image_url,
                                              duration=duration, quality=quality,
                                              aspect_ratio=aspect_ratio)
                    await status.edit_text(f"Working{tag}… (task {task_id[:18]})")
                    video_url = await poll_job(session, task_id)
                    data, size = await fetch_bytes(session, video_url)
                except Exception as e:  # noqa: BLE001
                    log.exception("clip %d failed", i + 1)
                    await bot.send_message(chat_id, f"Clip{tag} failed: {e}")
                    continue

                # Cache for repeat/edit
                rid = uuid.uuid4().hex[:12]
                _repeat_cache[rid] = {
                    "type": "video",
                    "prompt": prompt,
                    "caption": caption,
                    "image_url": image_url,
                    "image_bytes": image_bytes,
                    "duration": duration,
                    "quality": quality,
                    "aspect_ratio": aspect_ratio,
                    "count": 1,
                    "chat_id": chat_id,
                }
                btns = [
                    InlineKeyboardButton("🔁", callback_data=f"vrep:{rid}"),
                    InlineKeyboardButton("👁️", callback_data=f"vshp:{rid}"),
                    InlineKeyboardButton("💬", callback_data=f"vdlg:{rid}"),
                    InlineKeyboardButton("📝", callback_data=f"vprm:{rid}"),
                ]
                vid_kb = InlineKeyboardMarkup([btns])

                base = f"{caption}{tag}" if caption else tag.strip()
                if data is None:
                    await bot.send_message(chat_id,
                        f"Video{tag} is {size/1_048_576:.1f} MB — too big for Telegram.\n"
                        f"Link (expires 24h, save now):\n{video_url}",
                        reply_markup=vid_kb)
                else:
                    await bot.send_video(chat_id, video=data,
                                         caption=(base or None),
                                         supports_streaming=True,
                                         reply_markup=vid_kb)
                any_sent = True

            credits_after = await get_credits(session)
            if credits_after is not None and credits_before is not None:
                used = max(credits_before - credits_after, 0)
                await bot.send_message(chat_id,
                    f"💳 {used:.2f} · {credits_after:.2f} left")
            elif credits_after is not None:
                await bot.send_message(chat_id,
                    f"💳 {credits_after:.2f} left")
            return any_sent
    except Exception as e:  # noqa: BLE001
        log.exception("generation failed")
        await bot.send_message(chat_id, f"Failed: {e}")
        return False
    finally:
        try:
            await status.delete()
        except Exception:  # noqa: BLE001
            pass


# ---------------------------------------------------------------------------
# Image edit generation core
# ---------------------------------------------------------------------------
async def submit_image_job(session: aiohttp.ClientSession, prompt: str,
                           image_urls: list[str], *, img_size: str,
                           img_quality: str) -> str:
    payload = {
        "model": IMAGE_MODEL,
        "prompt": prompt,
        "size": img_size,
        "quality": img_quality,
        "n": 1,
        "output_format": "png",
        "watermark": False,
    }
    if image_urls:
        payload["image_urls"] = image_urls
    headers = {"Authorization": f"Bearer {EVOLINK_KEY}"}
    async with session.post(IMAGE_GEN_URL, json=payload, headers=headers) as r:
        body = await r.json()
        log.info("submit_image_job %d: %s", r.status, json.dumps(body)[:500])
        if r.status == 401:
            raise RuntimeError("EvoLink rejected the key (401).")
        if r.status == 402:
            raise RuntimeError("EvoLink balance too low (402). Top up credits.")
        if r.status >= 400:
            raise RuntimeError(f"Image submit error {r.status}: {body}")
        task_id = body.get("id")
        if not task_id:
            raise RuntimeError(f"No task id returned: {body}")
        return task_id


async def run_image_edit(bot, chat_id, *, prompt, image_bytes_list,
                         img_size, img_quality):
    """Upload image(s), submit Seedream job, poll, send result photo.
    image_bytes_list can be empty for text-to-image.
    Runs as an asyncio background task."""
    count = len(image_bytes_list)
    status = await bot.send_message(chat_id,
        f"Uploading {count} image{'s' if count != 1 else ''}…" if count else "Generating…")
    timeout = aiohttp.ClientTimeout(total=None)  # no session-level cap; poll_job has its own
    try:
        async with aiohttp.ClientSession(timeout=timeout) as session:
            credits_before = await get_credits(session)
            image_urls = []
            for i, img_bytes in enumerate(image_bytes_list):
                url = await upload_image(session, img_bytes,
                                         filename=f"img_{i}.jpg")
                image_urls.append(url)

            await status.edit_text("Editing image… 10–45s.")
            task_id = await submit_image_job(session, prompt, image_urls,
                                              img_size=img_size,
                                              img_quality=img_quality)
            await status.edit_text(f"⏳ {task_id}")
            result_url = await poll_job(session, task_id)

            # Cache params for repeat
            rid = uuid.uuid4().hex[:12]
            _repeat_cache[rid] = {
                "prompt": prompt,
                "image_bytes_list": image_bytes_list,
                "img_size": img_size,
                "img_quality": img_quality,
                "chat_id": chat_id,
                "result_bytes": None,  # filled below if download succeeds
            }
            repeat_kb = InlineKeyboardMarkup([[
                InlineKeyboardButton("🔁", callback_data=f"rep:{rid}"),
                InlineKeyboardButton("👁️", callback_data=f"shp:{rid}"),
                InlineKeyboardButton("✏️", callback_data=f"edp:{rid}"),
                InlineKeyboardButton("🖌️", callback_data=f"edr:{rid}"),
            ]])

            data, size = await fetch_bytes(session, result_url)
            if data is None:
                await bot.send_message(chat_id,
                    f"Image is {size/1_048_576:.1f} MB — too big for Telegram.\n"
                    f"Link (expires 24h):\n{result_url}",
                    reply_markup=repeat_kb)
            else:
                _repeat_cache[rid]["result_bytes"] = data
                await bot.send_photo(chat_id, photo=data,
                                     reply_markup=repeat_kb)

            credits_after = await get_credits(session)
            if credits_after is not None and credits_before is not None:
                used = max(credits_before - credits_after, 0)
                await bot.send_message(chat_id,
                    f"💳 {used:.2f} · {credits_after:.2f} left")
            elif credits_after is not None:
                await bot.send_message(chat_id,
                    f"💳 {credits_after:.2f} left")
            return True
    except Exception as e:
        log.exception("image edit failed")
        await bot.send_message(chat_id, f"Failed: {e}")
        return False
    finally:
        try:
            await status.delete()
        except Exception:
            pass


# ---------- THRONE MODE ----------

THRONE_TYPE_KEYBOARD = ReplyKeyboardMarkup(
    [["❌ Failed", "🚫 Cancelled"], [BTN_CANCEL]],
    resize_keyboard=True, one_time_keyboard=False,
)

async def throne_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Entry point for the Throne button."""
    if not image_authorised(update):
        return ConversationHandler.END
    context.user_data.clear()
    await clear_close(update, context)
    track(context, update.message.message_id)
    await say(
        update, context,
        "👑 *Throne Generator*\n\nChoose the status type:",
        THRONE_TYPE_KEYBOARD,
    )
    return THRONE_WAIT


THRONE_AMOUNT_KEYBOARD = ReplyKeyboardMarkup(
    [[BTN_BACK, BTN_CANCEL]],
    resize_keyboard=True, one_time_keyboard=False,
)

async def throne_input(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Step 1: pick Failed or Cancelled. Step 2: enter time + amount."""
    if not image_authorised(update):
        return ConversationHandler.END

    track(context, update.message.message_id)
    text = (update.message.text or "").strip()

    # Step 1 — variant not chosen yet
    if "throne_variant" not in context.user_data:
        if text == "❌ Failed":
            context.user_data["throne_variant"] = "failed"
        elif text == "🚫 Cancelled":
            context.user_data["throne_variant"] = "cancelled"
        else:
            await say(update, context,
                "Choose a status type:", THRONE_TYPE_KEYBOARD)
            return THRONE_WAIT
        label = "Failed" if context.user_data["throne_variant"] == "failed" else "Cancelled"
        await say(update, context,
            f"👑 *{label}* selected.\n\n"
            "Now send time and amount, e.g. `23:45 40`",
            THRONE_AMOUNT_KEYBOARD)
        return THRONE_WAIT

    # Back → restart
    if text == BTN_BACK:
        context.user_data.pop("throne_variant", None)
        await say(update, context,
            "👑 *Throne Generator*\n\nChoose the status type:",
            THRONE_TYPE_KEYBOARD)
        return THRONE_WAIT

    # Step 2 — parse time + amount
    parsed = _parse_throne_input(text)
    if parsed is None:
        await say(
            update, context,
            "⚠️ Format: `TIME AMOUNT`  e.g. `23:45 40`\n"
            "Amount must be a positive integer.",
            THRONE_AMOUNT_KEYBOARD,
        )
        return THRONE_WAIT

    time_str, amount = parsed
    variant = context.user_data.pop("throne_variant", "failed")
    await cleanup(update, context)

    asyncio.create_task(
        run_throne_edit(context.bot, update.effective_chat.id, time_str, amount, variant,
                        uid=update.effective_user.id)
    )

    label = "Failed" if variant == "failed" else "Cancelled"
    await close_msg(update, context,
        f"👑 Generating Throne ({label}) for {time_str} · ${amount}…")
    return ConversationHandler.END


# ---------- IMAGE EDIT MODE ----------
MAX_EDIT_IMAGES = 5  # 1 target + up to 4 refs

async def img_edit_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not image_authorised(update):
        return ConversationHandler.END
    context.user_data.clear()
    await clear_close(update, context)
    track(context, update.message.message_id)
    context.user_data["image_list"] = []
    await say(update, context, "📷 or ✏️", CANCEL_KEYBOARD)
    return IMG_EDIT_REFS


async def img_edit_refs(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Photo → add to list. Text → prompt (with or without photos)."""
    if not image_authorised(update):
        return ConversationHandler.END
    track(context, update.message.message_id)

    if update.message.text == BTN_BACK:
        img_list = context.user_data.get("image_list", [])
        if img_list:
            img_list.pop()
            context.user_data["image_list"] = img_list
            n = len(img_list)
            if n == 0:
                await say(update, context, "📷 or ✏️", CANCEL_KEYBOARD)
            else:
                await say(update, context,
                          f"✅ {n} — ➕📷 or ✏️", BACK_CANCEL_KEYBOARD)
            return IMG_EDIT_REFS
        await cleanup(update, context)
        await close_msg(update, context, "Cancelled.")
        return ConversationHandler.END

    # Photo → add
    file_id = None
    if update.message.photo:
        file_id = update.message.photo[-1].file_id
    elif update.message.document and (update.message.document.mime_type or "").startswith("image/"):
        file_id = update.message.document.file_id

    if file_id:
        img_list = context.user_data.get("image_list", [])
        if len(img_list) >= MAX_EDIT_IMAGES:
            await say(update, context, f"🚫 max {MAX_EDIT_IMAGES} — ✏️",
                      BACK_CANCEL_KEYBOARD)
            return IMG_EDIT_REFS
        tg_file = await context.bot.get_file(file_id)
        img_list.append(bytes(await tg_file.download_as_bytearray()))
        context.user_data["image_list"] = img_list
        n = len(img_list)
        if n == 1:
            await say(update, context, "✅ 1 — ➕📷 or ✏️",
                      BACK_CANCEL_KEYBOARD)
        else:
            await say(update, context,
                      f"✅ {n} (+{n-1} ref) — ➕📷 or ✏️",
                      BACK_CANCEL_KEYBOARD)
        return IMG_EDIT_REFS

    # Text → prompt (works with or without photos)
    text = (update.message.text or "").strip()
    if not text:
        return IMG_EDIT_REFS

    context.user_data["edit_prompt"] = text
    img_list = context.user_data.get("image_list", [])
    n = len(img_list)
    if n == 0:
        label = "text-to-image"
    elif n == 1:
        label = "1 img"
    else:
        label = f"1 img +{n-1} ref"
    await say(update, context, f"\"{text}\" — {label} — Go?",
              CONFIRM_KEYBOARD)
    return IMG_EDIT_CONFIRM


async def img_edit_confirm(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not image_authorised(update):
        return ConversationHandler.END
    track(context, update.message.message_id)
    if update.message.text == BTN_BACK:
        n = len(context.user_data.get("image_list", []))
        await say(update, context, f"✅ {n} — ➕📷 or ✏️",
                  BACK_CANCEL_KEYBOARD)
        return IMG_EDIT_REFS
    if update.message.text != BTN_GENERATE:
        await say(update, context, "Go, Back, or Cancel.", CONFIRM_KEYBOARD)
        return IMG_EDIT_CONFIRM

    prompt = context.user_data.get("edit_prompt")
    img_list = context.user_data.get("image_list", [])
    if not prompt:
        await cleanup(update, context)
        await close_msg(update, context, "Lost data — restart.")
        return ConversationHandler.END

    await cleanup(update, context)
    _uid = update.effective_user.id
    _log_usage(_uid, _estimate_image_edit_cost(get_image_quality()), "image_edit")
    asyncio.create_task(run_image_edit(
        context.bot, update.effective_chat.id,
        prompt=prompt, image_bytes_list=img_list,
        img_size=get_image_size(), img_quality=get_image_quality(),
    ))
    await close_msg(update, context, "⏳ Queued.")
    return ConversationHandler.END


