# ---------- USAGE FLOW ----------

async def usage_period(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Step 2: user picked a period — show per-user breakdown + user picker."""
    if not image_authorised(update):
        return ConversationHandler.END
    track(context, update.message.message_id)
    text = (update.message.text or "").strip()

    if text == BTN_BACK:
        return await show_settings(update, context)

    if text not in (BTN_USAGE_DAY, BTN_USAGE_WEEK, BTN_USAGE_MONTH, BTN_USAGE_ALL):
        await say(update, context, "Pick a period:", USAGE_PERIOD_KEYBOARD)
        return USAGE_PERIOD

    context.user_data["usage_period_btn"] = text
    since, label = _since_for_period(text)

    all_uids = _all_tracked_uids()
    summary = _usage_summary(all_uids, since, label)

    kb = _usage_keyboard()
    await say(update, context,
              summary + "\n\n👤 Tap a user for their detailed breakdown:",
              kb)
    return USAGE_USER


async def usage_user(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Step 3: user tapped a name — show that user's breakdown."""
    if not image_authorised(update):
        return ConversationHandler.END
    track(context, update.message.message_id)
    text = (update.message.text or "").strip()

    if text == BTN_BACK:
        # Go back to period picker, re-show overview
        await say(update, context,
                  "Pick a period to see per-user breakdown:",
                  USAGE_PERIOD_KEYBOARD)
        return USAGE_PERIOD

    period_btn = context.user_data.get("usage_period_btn", BTN_USAGE_ALL)
    since, label = _since_for_period(period_btn)

    uid = _usage_uid_by_name(text)
    if uid is None:
        await say(update, context, "Unknown user — tap a name below:",
                  _usage_keyboard())
        return USAGE_USER

    summary = _usage_summary([uid], since, f"{text} — {label}")
    await say(update, context, summary, _usage_keyboard())
    return USAGE_USER


# ---------- shared cancel ----------
async def cancel(update: Update, context: ContextTypes.DEFAULT_TYPE):
    track(context, update.message.message_id)
    await cleanup(update, context)
    await close_msg(update, context, "Cancelled.")
    return ConversationHandler.END


async def balance(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not image_authorised(update):
        return
    async with aiohttp.ClientSession() as session:
        bal = await get_credits(session)
    if bal is None:
        await update.message.reply_text("Couldn't fetch the balance right now.")
    else:
        await update.message.reply_text(f"💳 {bal:.2f} credits remaining.")


async def grant_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin: /grant <uid> [name] [uid2] [name2] ...
    Each ID can be followed by a name (non-numeric). E.g.:
      /grant 123456 Alice 789012 Bob 345678
    """
    if not authorised(update):
        return
    if not context.args:
        await update.message.reply_text("/grant <user_id> [name] [user_id2] [name2] ...")
        return
    ok, bad = [], []
    args = list(context.args)
    while args:
        arg = args.pop(0)
        try:
            uid = int(arg)
            # Check if next token is a name (non-numeric)
            name = ""
            if args and not args[0].lstrip("-").isdigit():
                name = args.pop(0)
            _grant_full_user(uid, name)
            label = f"{uid} ({name})" if name else str(uid)
            ok.append(label)
        except ValueError:
            bad.append(arg)
    lines = []
    if ok:
        lines.append("✅ Granted full access: " + ", ".join(ok))
    if bad:
        lines.append("⚠️ Skipped (not valid IDs): " + ", ".join(bad))
    await update.message.reply_text("\n".join(lines))


async def revoke_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin: /revoke <uid1> [uid2 ...] — remove access from one or more users."""
    if not authorised(update):
        return
    if not context.args:
        await update.message.reply_text("/revoke <user_id> [user_id2 ...]")
        return
    ok, bad = [], []
    for arg in context.args:
        try:
            uid = int(arg)
            _revoke_full_user(uid)
            ok.append(uid)
        except ValueError:
            bad.append(arg)
    lines = []
    if ok:
        lines.append("❌ Revoked: " + ", ".join(str(u) for u in ok))
    if bad:
        lines.append("⚠️ Skipped (not valid IDs): " + ", ".join(bad))
    await update.message.reply_text("\n".join(lines))


async def users_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin: /users — list all granted users with names."""
    if not authorised(update):
        return
    full_users = _get_full_users()
    img_only = _get_image_users() - full_users
    def fmt(uid):
        name = _get_user_name(uid)
        return f"{name} ({uid})" if name != str(uid) else str(uid)
    lines = []
    if full_users:
        lines.append("Full access:\n" + "\n".join(f"  {fmt(u)}" for u in sorted(full_users)))
    if img_only:
        lines.append("Image only:\n" + "\n".join(f"  {fmt(u)}" for u in sorted(img_only)))
    if not lines:
        await update.message.reply_text("No granted users.")
        return
    await update.message.reply_text("\n".join(lines))


async def usage_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin: /usage [period] [user_id]
    period: today | week | month | all  (default: today)
    user_id: optional, show one user; omit for all tracked users.
    Examples:
      /usage                → all users, today
      /usage week           → all users, last 7 days
      /usage month 123456   → user 123456, last 30 days
      /usage all            → all users, all time
    """
    if not authorised(update):
        return

    args = list(context.args or [])
    period = "today"
    target_uid = None

    # Parse optional period keyword
    if args and args[0].lower() in ("today", "week", "month", "all"):
        period = args.pop(0).lower()

    # Parse optional user_id
    if args:
        try:
            target_uid = int(args[0])
        except ValueError:
            await update.message.reply_text(
                "Usage: /usage [today|week|month|all] [user_id]")
            return

    now = datetime.datetime.utcnow()
    if period == "today":
        since = now.replace(hour=0, minute=0, second=0, microsecond=0)
        label = "today (UTC)"
    elif period == "week":
        since = now - datetime.timedelta(days=7)
        label = "last 7 days"
    elif period == "month":
        since = now - datetime.timedelta(days=30)
        label = "last 30 days"
    else:
        since = None
        label = "all time"

    uids = [target_uid] if target_uid else _all_tracked_uids()
    if not uids:
        await update.message.reply_text("No usage data recorded yet.")
        return

    lines = [f"📊 Credit usage — {label}"]
    grand_total = 0.0
    for uid in uids:
        entries = _get_usage(uid, since)
        # Exclude throne (gpt-image-2) from tracked usage
        entries = [e for e in entries if e.get("mode") != "throne"]
        if not entries:
            if target_uid:
                lines.append(f"  {_get_user_name(uid)}: no data for this period")
            continue
        total = sum(e["credits"] for e in entries)
        grand_total += total
        by_mode: dict[str, float] = {}
        for e in entries:
            by_mode[e["mode"]] = by_mode.get(e["mode"], 0) + e["credits"]
        breakdown = " | ".join(f'{m}: {v:.2f}' for m, v in sorted(by_mode.items()))
        name = _get_user_name(uid)
        lines.append(f"  {name}: {total:.2f} cr  ({breakdown})")

    if len(uids) > 1:
        lines.append(f"Total: {grand_total:.2f} credits")

    await update.message.reply_text("\n".join(lines))


async def repeat_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle inline button presses for image and video results."""
    query = update.callback_query
    await query.answer()
    if not query.data:
        return
    action, _, rid = query.data.partition(":")
    if not rid:
        return
    params = _repeat_cache.get(rid)
    if not params:
        await query.answer("expired", show_alert=True)
        return

    # ---- IMAGE actions ----
    if action == "rep":
        asyncio.create_task(run_image_edit(
            context.bot, params["chat_id"],
            prompt=params["prompt"],
            image_bytes_list=params["image_bytes_list"],
            img_size=params["img_size"],
            img_quality=params["img_quality"],
        ))

    elif action == "shp":
        await context.bot.send_message(
            params["chat_id"], f"📝 {params['prompt']}")

    elif action == "edp":
        context.user_data["editing_rid"] = rid
        context.user_data["editing_type"] = "image"
        context.user_data.pop("editing_result", None)
        await context.bot.send_message(params["chat_id"], "✏️")

    elif action == "edr":
        result_bytes = params.get("result_bytes")
        if not result_bytes:
            await query.answer("no result data", show_alert=True)
            return
        context.user_data["editing_result"] = {
            "base_bytes": result_bytes,
            "refs": [],
            "img_size": params["img_size"],
            "img_quality": params["img_quality"],
        }
        context.user_data.pop("editing_rid", None)
        await context.bot.send_message(
            params["chat_id"], "➕📷 or ✏️")

    # ---- VIDEO actions ----
    elif action == "vrep":
        asyncio.create_task(run_generation(
            context.bot, params["chat_id"],
            prompt=params["prompt"], caption=params["caption"],
            image_url=params.get("image_url"),
            image_bytes=params.get("image_bytes"),
            duration=params["duration"], quality=params["quality"],
            aspect_ratio=params["aspect_ratio"], count=1,
        ))

    elif action == "vshp":
        await context.bot.send_message(
            params["chat_id"], f"📝 {params['prompt']}")

    elif action == "vdlg":
        context.user_data["editing_rid"] = rid
        context.user_data["editing_type"] = "video_dlg"
        context.user_data.pop("editing_result", None)
        await context.bot.send_message(params["chat_id"], "💬")

    elif action == "vprm":
        context.user_data["editing_rid"] = rid
        context.user_data["editing_type"] = "video_prm"
        context.user_data.pop("editing_result", None)
        await context.bot.send_message(params["chat_id"], "📝")


async def img_action_catch(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Catch text/photos after inline button taps (image edit, video edit)."""

    # --- ✏️/💬/📝 edit prompt/dialogue ---
    rid = context.user_data.get("editing_rid")
    if rid:
        text = (update.message.text or "").strip()
        if not text:
            return
        context.user_data.pop("editing_rid", None)
        edit_type = context.user_data.pop("editing_type", "image")
        params = _repeat_cache.get(rid)
        if not params:
            await update.message.reply_text("expired")
            return

        if edit_type == "image":
            asyncio.create_task(run_image_edit(
                context.bot, update.effective_chat.id,
                prompt=text,
                image_bytes_list=params["image_bytes_list"],
                img_size=params["img_size"],
                img_quality=params["img_quality"],
            ))
        elif edit_type == "video_dlg":
            new_prompt = load_template().format(dialogue=text)
            asyncio.create_task(run_generation(
                context.bot, update.effective_chat.id,
                prompt=new_prompt, caption=text,
                image_url=params.get("image_url"),
                image_bytes=params.get("image_bytes"),
                duration=params["duration"], quality=params["quality"],
                aspect_ratio=params["aspect_ratio"], count=1,
            ))
        elif edit_type == "video_prm":
            asyncio.create_task(run_generation(
                context.bot, update.effective_chat.id,
                prompt=text, caption="",
                image_url=params.get("image_url"),
                image_bytes=params.get("image_bytes"),
                duration=params["duration"], quality=params["quality"],
                aspect_ratio=params["aspect_ratio"], count=1,
            ))
        return

    # --- 🖌️ edit result: result as base, optional refs, then prompt ---
    er = context.user_data.get("editing_result")
    if not er:
        return

    file_id = None
    if update.message.photo:
        file_id = update.message.photo[-1].file_id
    elif update.message.document and (update.message.document.mime_type or "").startswith("image/"):
        file_id = update.message.document.file_id

    if file_id:
        if len(er["refs"]) >= MAX_EDIT_IMAGES - 1:
            await update.message.reply_text(f"🚫 max {MAX_EDIT_IMAGES - 1} refs — ✏️")
            return
        tg_file = await context.bot.get_file(file_id)
        er["refs"].append(bytes(await tg_file.download_as_bytearray()))
        refs = len(er["refs"])
        await update.message.reply_text(f"✅ +{refs} — ➕📷 or ✏️")
        return

    text = (update.message.text or "").strip()
    if not text:
        return
    context.user_data.pop("editing_result", None)
    image_list = [er["base_bytes"]] + er["refs"]
    asyncio.create_task(run_image_edit(
        context.bot, update.effective_chat.id,
        prompt=text,
        image_bytes_list=image_list,
        img_size=er["img_size"],
        img_quality=er["img_quality"],
    ))


def main():
    app = (
        Application.builder()
        .token(BOT_TOKEN)
        .read_timeout(60)
        .write_timeout(60)
        .connect_timeout(30)
        .build()
    )

    cancel_filter = filters.Regex(f"^{BTN_CANCEL}$")
    txt = filters.TEXT & ~filters.COMMAND & ~cancel_filter
    img = (filters.PHOTO | filters.Document.IMAGE) & ~filters.COMMAND

    conv = ConversationHandler(
        entry_points=[
            MessageHandler(filters.Regex(f"^{BTN_QUICK}$"), quick_start),
            MessageHandler(filters.Regex(f"^{BTN_FLEX}$"), flex_start),
            MessageHandler(filters.Regex(r"^🖌️ Edit$"), img_edit_start),
            MessageHandler(filters.Regex(f"^{re.escape(BTN_THRONE)}$"), throne_start),
            MessageHandler(filters.Regex(f"^{BTN_SETTINGS}$"), settings_start),
        ],
        states={
            QUICK_DIALOGUE: [MessageHandler(txt, quick_dialogue)],
            QUICK_CONFIRM:  [MessageHandler(txt, quick_confirm)],
            FLEX_IMAGE:     [MessageHandler(img | txt, flex_image)],
            FLEX_PROMPTTYPE:[MessageHandler(txt, flex_prompttype)],
            FLEX_TEXT:      [MessageHandler(txt, flex_text)],
            FLEX_CONFIRM:   [MessageHandler(txt, flex_confirm)],
            SET_IMAGE_WAIT: [MessageHandler(img | txt, settings_router)],
            EDIT_PROMPT_WAIT: [MessageHandler(txt, edit_prompt_wait)],
            PICK_DURATION: [MessageHandler(txt, pick_duration)],
            PICK_QUALITY: [MessageHandler(txt, pick_quality)],
            PICK_ASPECT: [MessageHandler(txt, pick_aspect)],
            PICK_COUNT: [MessageHandler(txt, pick_count)],
            PICK_IMG_QUALITY: [MessageHandler(txt, pick_img_quality)],
            PICK_IMG_SIZE: [MessageHandler(txt, pick_img_size)],
            IMG_EDIT_REFS: [MessageHandler(img | txt, img_edit_refs)],
            IMG_EDIT_CONFIRM: [MessageHandler(txt, img_edit_confirm)],
            THRONE_WAIT: [MessageHandler(txt, throne_input)],
            USAGE_PERIOD: [MessageHandler(txt, usage_period)],
            USAGE_USER:   [MessageHandler(txt, usage_user)],
        },
        fallbacks=[
            CommandHandler("cancel", cancel),
            MessageHandler(cancel_filter, cancel),
        ],
    )

    app.add_handler(CommandHandler("start", start))
    app.add_handler(CommandHandler("balance", balance))
    app.add_handler(CommandHandler("grant", grant_cmd))
    app.add_handler(CommandHandler("revoke", revoke_cmd))
    app.add_handler(CommandHandler("users", users_cmd))
    app.add_handler(CommandHandler("usage", usage_cmd))
    app.add_handler(CallbackQueryHandler(repeat_callback, pattern=r"^(rep|shp|edp|edr|vrep|vshp|vdlg|vprm):"))
    app.add_handler(conv)
    # Catch text/photos after inline button taps (runs only when no conv is active)
    app.add_handler(MessageHandler(
        (filters.TEXT | filters.PHOTO | filters.Document.IMAGE) & ~filters.COMMAND,
        img_action_catch
    ))
    log.info("Bot starting (long-polling)…")
    app.run_polling(allowed_updates=Update.ALL_TYPES)


if __name__ == "__main__":
    main()
